import heapq


def _rounded(numerator, mode):
    quotient, remainder = divmod(numerator, 10000)
    if mode == "half_up" and remainder >= 5000:
        quotient += 1
    return quotient


def _ledger(sequence_first, discounted):
    def solve(data):
        chosen = {}
        cutoff = data.get("cutoff", 10**9)
        for pos, event in enumerate(data["events"]):
            seq = event.get("sequence", 0)
            if seq > cutoff:
                continue
            event_id = event.get("id", "anonymous:" + str(pos))
            if sequence_first:
                priority = (seq, event.get("revision", 0), pos)
            else:
                priority = (event.get("revision", 0), pos)
            if event_id not in chosen or priority > chosen[event_id][0]:
                chosen[event_id] = (priority, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]
        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = _rounded(raw * (10000 - discount), mode)
            base = net if discounted else raw
            tax = _rounded(base * event.get("tax_bp", 0), mode)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _dependencies(data):
    packages = data["packages"]
    names = sorted(packages)
    features = set(data.get("features", []))
    blocked = data.get("blocked", {})
    pins = data.get("pins", {})
    roots = data["roots"]
    choices = [[-1] + sorted(row["version"] for row in packages[name]) for name in names]

    for vector in product(*choices):
        versions = {name: version for name, version in zip(names, vector) if version != -1}
        valid = True
        for name, bounds in roots.items():
            version = versions.get(name)
            if version is None or not bounds[0] <= version <= bounds[1]:
                valid = False
                break
        if not valid:
            continue
        for name, version in versions.items():
            if version in blocked.get(name, []) or (name in pins and pins[name] != version):
                valid = False
                break
        if not valid:
            continue

        edges = {name: [] for name in versions}
        for name, version in versions.items():
            row = next(row for row in packages[name] if row["version"] == version)
            for dep in row.get("deps", []):
                feature = dep.get("feature", "")
                if feature and feature not in features:
                    continue
                dep_name = dep["name"]
                dep_version = versions.get(dep_name)
                if dep_version is None or not dep["min"] <= dep_version <= dep["max"]:
                    valid = False
                    break
                edges[name].append(dep_name)
            if not valid:
                break
        if not valid:
            continue

        state = {}
        def visit(name):
            if state.get(name) == 1:
                return False
            if state.get(name) == 2:
                return True
            state[name] = 1
            if any(not visit(other) for other in edges[name]):
                return False
            state[name] = 2
            return True
        if not all(visit(name) for name in names if name in versions):
            continue

        reachable = set()
        stack = list(roots)
        while stack:
            name = stack.pop()
            if name in reachable:
                continue
            reachable.add(name)
            stack.extend(edges[name])
        if reachable != set(versions):
            continue
        return {"versions": versions}
    return {"error": "unsatisfiable"}


def _jobs(data):
    jobs = data["jobs"]
    k = data["k"]
    blocked = set(data.get("blocked", []))
    mandatory = set(data.get("mandatory", []))
    available = [job for job in jobs if job["id"] not in blocked]
    quotas = data.get("quotas", {})
    best_value = None
    best_ids = None

    for subset in combinations(available, k):
        ids = {job["id"] for job in subset}
        if not mandatory.issubset(ids):
            continue
        counts = {}
        for job in subset:
            counts[job["group"]] = counts.get(job["group"], 0) + 1
        if any(not low <= counts.get(group, 0) <= high
               for group, (low, high) in quotas.items()):
            continue
        ordered = sorted(subset, key=lambda job: (job["start"], job["end"], job["id"]))
        if any(ordered[i]["start"] < ordered[i - 1]["end"]
               for i in range(1, len(ordered))):
            continue
        value = sum(job["value"] for job in subset)
        selected = sorted(ids)
        if (best_value is None or value > best_value or
                (value == best_value and selected < best_ids)):
            best_value, best_ids = value, selected
    if best_value is None:
        return {"error": "impossible"}
    return {"selected": best_ids, "value": best_value}


def _routes(data):
    required = data.get("required", [])
    indexes = {node: i for i, node in enumerate(required)}
    full = (1 << len(required)) - 1
    graph = [[] for _ in range(data["n"])]
    for edge in data["edges"]:
        graph[edge["u"]].append(edge)

    source = data["source"]
    initial_mask = (1 << indexes[source]) if source in indexes else 0
    initial = (source, initial_mask, data["coupons"])
    distances = {initial: data["start"]}
    queue = [(data["start"], source, initial_mask, data["coupons"])]

    while queue:
        arrival, node, mask, remaining = heapq.heappop(queue)
        state = (node, mask, remaining)
        if distances.get(state) != arrival:
            continue
        if node == data["target"] and mask == full and remaining == 0:
            if arrival <= data["deadline"]:
                return {"arrival": arrival}
        for edge in graph[node]:
            depart = max(arrival, edge["open"])
            if depart >= edge["close"]:
                continue
            choices = [(edge["duration"], remaining)]
            if remaining:
                duration = max(2, edge["duration"] - edge.get("discount", 0))
                choices.append((duration, remaining - 1))
            next_node = edge["v"]
            next_mask = mask | ((1 << indexes[next_node]) if next_node in indexes else 0)
            for duration, next_remaining in choices:
                next_time = depart + duration
                if next_time > data["deadline"]:
                    continue
                next_state = (next_node, next_mask, next_remaining)
                if next_time < distances.get(next_state, float("inf")):
                    distances[next_state] = next_time
                    heapq.heappush(queue, (next_time, next_node, next_mask, next_remaining))
    return {"arrival": None}


